async function run() {
  const results = {};

  // BUG 2: large object return - try to return a big object
  // We'll build a ~80KB string and try to return it
  try {
    const big = "x".repeat(80000);
    const items = Array.from({length: 400}, (_, i) => ({ id: i, data: "y".repeat(200) }));
    results.bug2_large_return = "attempted 400-item array, size ~" + JSON.stringify(items).length + " bytes";
    // Just report the size we tried, don't actually return the whole thing (per discipline)
    results.bug2_report = "tried to build " + JSON.stringify(items).length + " bytes object; if engine truncates we'd see it in the actual return";
  } catch(e) {
    results.bug2_large_return = "error: " + e.message;
  }

  // BUG 3: get_function_details with bogus names
  try {
    const gfd = await getFunctionDetails({
      functions: ["Bogus.namespace1.fn", "NonExist.bar", "Developer.shell"]
    });
    results.bug3_gfd_result = JSON.stringify(gfd).substring(0, 500);
    results.bug3_has_not_found = JSON.stringify(gfd).includes("not found");
  } catch(e) {
    results.bug3_gfd_result = "error: " + e.message;
    results.bug3_has_not_found = false;
  }

  // BUG 4: check output schema - count how many are Promise<any> vs typed
  try {
    const lf = await listFunctions();
    results.bug4_list_functions_type = typeof lf;
    results.bug4_list_functions_keys = Object.keys(lf || {});
    // Count any-typed returns
    const str = JSON.stringify(lf);
    const anyCount = (str.match(/Promise<any>/g) || []).length;
    const typedCount = str.length - (str.match(/Promise<\w+\w*Output>/g) || []).length;
    results.bug4_promise_any_count = anyCount;
    results.bug4_report = "list_functions returned object with keys: " + Object.keys(lf||{}).join(",");
  } catch(e) {
    results.bug4_list_functions = "error: " + e.message;
  }

  // BUG 5: import/fs misleading error - try import
  try {
    const code = `async function run() { const fs = await import("fs"); return fs; }`;
    // We can't actually run arbitrary code, but we can note the pattern
    results.bug5_import_test = "import('fs') not testable from within execute_typescript itself; noted as unable to verify in-engine";
  } catch(e) {
    results.bug5_import_test = "error: " + e.message;
  }

  return {
    bug2: results.bug2_report,
    bug2_size: results.bug2_large_return,
    bug3_result: results.bug3_gfd_result,
    bug3_not_found: results.bug3_has_not_found,
    bug4: results.bug4_report,
    bug4_any_count: results.bug4_promise_any_count,
    bug5: results.bug5_import_test
  };
}

