async function run() {
  const r: Record<string, any> = {};

  // BUG 3: get_function_details with bogus names — check if "not found" is reported
  try {
    const gfd = await getFunctionDetails({
      functions: ["Bogus.ns.fn", "NonExist.bar", "Developer.shell"]
    });
    r.bug3_raw = JSON.stringify(gfd).substring(0, 600);
    r.bug3_has_not_found = JSON.stringify(gfd).includes("not found");
    r.bug3_reported_each = JSON.stringify(gfd).includes("Bogus");
  } catch (e: any) {
    r.bug3_error = e?.message || String(e);
  }

  // BUG 4: count Promise<any> vs typed from list_functions
  try {
    const lf = await listFunctions();
    const lfStr = JSON.stringify(lf);
    const anyCount = (lfStr.match(/Promise<any>/g) || []).length;
    const typedCount = (lfStr.match(/Promise<\w+Output>/g) || []).length;
    r.bug4_any_count = anyCount;
    r.bug4_typed_count = typedCount;
    r.bug4_total = anyCount + typedCount;
    // check if any "available" or "active" marker exists
    r.bug4_has_availability_marker = lfStr.includes("available") || lfStr.includes("inactive") || lfStr.includes("enabled");
  } catch (e: any) {
    r.bug4_error = e?.message || String(e);
  }

  // BUG 2: build a large object and check if engine truncates
  try {
    const items: Record<string, any>[] = [];
    for (let i = 0; i < 400; i++) {
      items.push({ id: i, data: "y".repeat(200) });
    }
    const jsonLen = JSON.stringify(items).length;
    r.bug2_built_size = jsonLen;
    // Return the full thing to see if engine truncates
    r.bug2_return_full = items; // this will test truncation
  } catch (e: any) {
